as x(id text, place jsonb, info jsonb, restaurants jsonb, "placesIntro" text, section text, sources jsonb);
create temp table _availability_foods_before on commit drop as table public.ieb_foods;
create temp table _availability_restaurants_before on commit drop as table public.ieb_restaurant;
do $$ declare item record; data jsonb; lang text; begin
 for item in select * from _availability_input loop
  select content into data from public.ieb_foods where id=item.id for update;
  if data is null or not (jsonb_array_length(coalesce(data->'places','[]'))=0 or
   (jsonb_array_length(data->'places')=1 and data#>>'{places,0,name}'=item.place->>'name')) then
   raise exception 'Expected an empty or previously applied list: %',item.id;
  end if;
  data:=jsonb_set(data,'{places}',jsonb_build_array(item.place));
  for lang in select unnest(array['ko','en','zh','ja']) loop
   if jsonb_typeof(data->lang)='object' then data:=jsonb_set(data,array[lang,'restaurants'],jsonb_build_array(item.info)); end if;
  end loop;
  data:=jsonb_set(data,'{manuscript,restaurants}',item.restaurants);
  data:=jsonb_set(data,'{manuscript,placesIntro}',to_jsonb(item."placesIntro"));
  data:=jsonb_set(data,'{manuscript,sections,3}',to_jsonb(item.section));
  update public.ieb_foods set content=data where id=item.id and content is distinct from data;
  insert into public.ieb_restaurant(name,address,opening_hours,closed_days,phone,naver_url,menu_info,food_ids,food_links,source_urls,verified_at)
  values(item.place->>'name',item.place->>'address',item.place->>'hours',item.place->>'holiday',coalesce(item.place->>'phone',''),coalesce(item.place->>'naverUrl',''),jsonb_build_array(item.info->>'signature'),array[item.id],
    jsonb_build_array(jsonb_build_object('food_id',item.id,'place_index',0,'signature',item.info->>'signature','source_place',item.place,'localized_info',jsonb_build_object('ko',item.info,'en',item.info,'zh',item.info,'ja',item.info))),
    array(select jsonb_array_elements_text(item.sources)),now()) on conflict(name,address) do nothing;
  if not exists(select 1 from public.ieb_restaurant where name=item.place->>'name' and address=item.place->>'address' and food_links @> jsonb_build_array(jsonb_build_object('food_id',item.id,'place_index',0))) then
   raise exception 'Restaurant master link mismatch: %',item.id;
  end if;
 end loop;
 if (select count(*) from public.ieb_foods where id in('yonggung-sundae','andong-heotjesatbap') and jsonb_array_length(coalesce(content->'places','[]'))=0)<>2 then
  raise exception 'Only the two reviewed empty food lists may be excluded';
 end if;
end $$;
update public.ieb_foods set content=jsonb_set(content,'{catalogStatus}','"archived"'::jsonb)
where id in('yonggung-sundae','andong-heotjesatbap') and content->>'catalogStatus' is distinct from 'archived';
do $$ begin
 if exists(select 1 from public.ieb_foods f join _availability_foods_before b using(id)
 where to_jsonb(f)-array['content','updated_at'] is distinct from to_jsonb(b)-array['content','updated_at'])
 or exists(select 1 from public.ieb_foods f join _availability_foods_before b using(id)
 where f.content is distinct from b.content and f.id not in(select id from _availability_input)
 and f.id not in('yonggung-sundae','andong-heotjesatbap'))
 or exists(select 1 from public.ieb_restaurant r join _availability_restaurants_before b using(id) where to_jsonb(r) is distinct from to_jsonb(b))
 then raise exception 'Unrelated food or existing restaurant data changed'; end if;
end $$;
select jsonb_build_object('restaurant_lists_added',(select count(*) from _availability_input),'excluded_empty_foods',(select jsonb_agg(id order by id) from public.ieb_foods where id in('yonggung-sundae','andong-heotjesatbap') and content->>'catalogStatus'='archived'),'active_foods',(select count(*) from public.ieb_foods where content->>'catalogStatus' is distinct from 'archived'),'restaurants',(select count(*) from public.ieb_restaurant),'out_of_scope_changes',0) as availability_result;
commit;
